{"code_snippet":"# Code analysis and execution of the selftest for scripts/metrics_from_lighthouse.py
import ast, runpy, sys

# Parse the source file to check syntax
path = 'scripts/metrics_from_lighthouse.py'
with open(path, 'r', encoding='utf-8') as f:
    src = f.read()

# Syntax check via ast
try:
    ast.parse(src)
    syntax_ok = True
except Exception as e:
    print('SYNTAX_ERROR:', e)
    syntax_ok = False

# Run the script's selftest by executing it with --selftest
if syntax_ok:
    try:
        sys_argv_backup = sys.argv[:]
        sys.argv = [path, '--selftest']
        try:
            runpy.run_path(path, run_name='__main__')
        finally:
            sys.argv = sys_argv_backup
        print('RUNTIME: selftest executed (no SystemExit)')
    except SystemExit as e:
        print('RUNTIME: SystemExit with code', e.code)
    except Exception as e:
        print('RUNTIME_ERROR:', repr(e))
else:
    print('Skipping runtime due to syntax errors')
